_IMPL_CLASS = None


def _implementation_class():
    global _IMPL_CLASS
    if _IMPL_CLASS is None:
        namespace = {
            "__name__": "splayer_embedded_hongguo",
            "__file__": __file__,
            "__package__": None,
        }
        source = lzma.decompress(base64.b85decode("".join(_IMPL_B85).encode("ascii")))
        exec(compile(source, __file__, "exec"), namespace, namespace)
        _IMPL_CLASS = namespace["Spider"]
    return _IMPL_CLASS


class Spider:
    name = "红果短剧"
    version_name = "0.3.8-ios"
    categories = [
        {"type_name": "漫剧", "type_id": "comic"},
        {"type_name": "短剧", "type_id": "short"},
        {"type_name": "榜单", "type_id": "rank"},
    ]

    def __init__(self):
        object.__setattr__(self, "_delegate", _implementation_class()())

    def __getattr__(self, name):
        return getattr(object.__getattribute__(self, "_delegate"), name)

    def getName(self):
        return self._delegate.getName()

    def init(self, extend=""):
        return self._delegate.init(extend)

    def homeContent(self, filter=False):
        return self._delegate.homeContent(filter)

    def homeVideoContent(self):
        return self._delegate.homeVideoContent()

    def categoryContent(self, tid, pg="1", filter=False, extend=None):
        return self._delegate.categoryContent(tid, pg, filter, extend)

    def detailContent(self, ids):
        return self._delegate.detailContent(ids)

    def searchContent(self, key, quick=False, pg="1"):
        return self._delegate.searchContent(key, quick, pg)

    def playerContent(self, flag, ref, vipFlags=None):
        return self._delegate.playerContent(flag, ref, vipFlags)

    def localProxy(self, param):
        return self._delegate.localProxy(param)

    def destroy(self):
        return self._delegate.destroy()

